<?php require __DIR__ . '/_shared.php';
if(session_status()!==PHP_SESSION_ACTIVE) session_start(); if(empty($_SESSION['aff_withdraw_csrf'])) $_SESSION['aff_withdraw_csrf']=bin2hex(random_bytes(24)); $csrf=$_SESSION['aff_withdraw_csrf']; $notice='';
$availableStmt=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM affiliate_rewards WHERE affiliate_id=? AND status='available'");$availableStmt->execute([$affiliateId]);$available=(float)$availableStmt->fetchColumn();
$heldStmt=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM withdrawals WHERE user_id=? AND status IN ('pending','approved','processing')");$heldStmt->execute([$userId]);$held=(float)$heldStmt->fetchColumn();$withdrawable=max(0,$available-$held);
if($_SERVER['REQUEST_METHOD']==='POST'){
 $token=(string)($_POST['csrf']??'');$amount=(float)($_POST['amount']??0);$network=trim((string)($_POST['network']??''));$phone=trim((string)($_POST['phone']??''));$name=trim((string)($_POST['account_name']??''));
 if(!hash_equals($csrf,$token)){error_log('DogoFlow affiliate payout CSRF mismatch for user '.$userId);$notice='Your session expired. Refresh and try again.';}
 elseif($amount<10){$notice='Minimum withdrawal is GH₵10.00.';}
 elseif(fmod($amount,10.0)!==0.0){$notice='Affiliate rewards are paid in GH₵10 increments. Choose a multiple of GH₵10.';}
 elseif($amount>$withdrawable+0.0001){$notice='The requested amount is greater than your withdrawable balance.';}
 elseif($network===''||$phone===''||$name===''){$notice='Please complete the Mobile Money details.';}
 else { $pdo->beginTransaction(); try{
  $userLock=$pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$userLock->execute([$userId]);
  $lock=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM affiliate_rewards WHERE affiliate_id=? AND status='available'");$lock->execute([$affiliateId]);$lockedAvailable=(float)$lock->fetchColumn();
  $heldLock=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM withdrawals WHERE user_id=? AND status IN ('pending','approved','processing')");$heldLock->execute([$userId]);$lockedHeld=(float)$heldLock->fetchColumn();
  if($amount>$lockedAvailable-$lockedHeld+0.0001) throw new RuntimeException('The requested amount is no longer available.');
  $ref='AFFWD-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(3)));$details=json_encode(['account_name'=>$name,'phone'=>$phone,'network'=>$network],JSON_UNESCAPED_SLASHES);$ins=$pdo->prepare("INSERT INTO withdrawals (user_id,amount,method,account_details,status,reference) VALUES (?,?,?,?, 'pending', ?)");$ins->execute([$userId,$amount,'mobile_money',$details,$ref]);$pdo->commit();$notice='Withdrawal request submitted successfully. Reference: '.$ref;$held += $amount;$withdrawable=max(0,$available-$held);
 }catch(Throwable $e){error_log('DogoFlow affiliate payout request failed for user '.$userId.': '.$e->getMessage()); if($pdo->inTransaction())$pdo->rollBack();$notice=$e instanceof RuntimeException?$e->getMessage():'We could not submit the request. Please try again.';}}
}
$stmt=$pdo->prepare("SELECT id,amount,method,account_details,status,reference,processed_at,created_at,payout_note FROM withdrawals WHERE user_id=? ORDER BY created_at DESC LIMIT 50");$stmt->execute([$userId]);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
aff_head('Withdrawals','withdrawals'); ?>
