<section class="mt-6 overflow-hidden rounded-2xl border bg-white shadow-sm"><div class="border-b p-5"><h2 class="font-extrabold">Withdrawal history</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-5 py-3">Reference</th><th class="px-5 py-3">Amount</th><th class="px-5 py-3">Method</th><th class="px-5 py-3">Status</th><th class="px-5 py-3">Date</th></tr></thead><tbody class="divide-y"><?php if(!$rows): ?><tr><td colspan="5" class="p-10 text-center text-slate-500">No withdrawal requests yet.</td></tr><?php else: foreach($rows as $r): [$cls,$x]=aff_status((string)$r['status']); ?><tr><td class="px-5 py-4 font-semibold"><?=e((string)$r['reference'])?></td><td class="px-5 py-4 font-bold">GH₵ <?=number_format((float)$r['amount'],2)?></td><td class="px-5 py-4 text-slate-500"><?=e(ucwords(str_replace('_',' ',(string)$r['method'])))?></td><td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-bold <?=$cls?>"><?=e(aff_label((string)$r['status']))?></span></td><td class="px-5 py-4 text-slate-500"><?=e(date('d M Y, H:i',strtotime((string)$r['created_at'])))?></td></tr><?php endforeach; endif; ?></tbody></table></div></section><?php aff_foot();
